CREATE OR REPLACE FUNCTION public.archive_outbound_mail()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.sender_mailbox_id IS NULL THEN RETURN NEW; END IF;
 -- Out-of-scope legacy fixture/provenance never becomes a readable asset.
 IF NOT EXISTS(SELECT 1 FROM mailboxes m JOIN domain_zones z ON z.id=NEW.zone_id AND z.tenant_id=NEW.tenant_id
     WHERE m.id=NEW.sender_mailbox_id AND m.tenant_id=NEW.tenant_id) THEN RETURN NEW; END IF;
 INSERT INTO sent_mail_assets(id,tenant_id,sender_mailbox_id,zone_id,mail_from,to_addrs,cc_addrs,subject,text_body,html_body,headers_json,template_version_id,created_at,search_text)
 VALUES(NEW.id,NEW.tenant_id,NEW.sender_mailbox_id,NEW.zone_id,NEW.mail_from,COALESCE(NEW.to_addrs,'{}'),COALESCE(NEW.cc_addrs,'{}'),NEW.subject,COALESCE(NEW.text_body,''),COALESCE(NEW.html_body,''),NEW.headers_json,NEW.template_version_id,NEW.created_at,
 concat_ws(E'\n',NEW.subject,NEW.mail_from,array_to_string(NEW.to_addrs,','),array_to_string(NEW.cc_addrs,','),NEW.text_body));
 INSERT INTO sent_mail_items(tenant_id,asset_id,mailbox_id,created_at,expires_at)
 SELECT NEW.tenant_id,NEW.id,NEW.sender_mailbox_id,NEW.created_at,
 CASE WHEN m.mailbox_kind='shared' AND m.retention_hours_override>0 THEN NEW.created_at+make_interval(hours=>m.retention_hours_override) ELSE NULL END
 FROM mailboxes m WHERE m.id=NEW.sender_mailbox_id AND m.tenant_id=NEW.tenant_id;
 INSERT INTO mailbox_event_log(tenant_id,mailbox_id,event_type,message_id) VALUES(NEW.tenant_id,NEW.sender_mailbox_id,'sent.created',NEW.id);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.capture_sent_recipient_snapshot_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE recipients TEXT[];
BEGIN
 NEW.bcc_addrs := NULL;
 NEW.recipient_completeness := 'legacy_unknown';
 NEW.recipient_snapshot_version := 0;
 SELECT j.bcc_addrs INTO recipients FROM outbound_jobs j
  WHERE j.tenant_id=NEW.tenant_id AND j.id=NEW.id
   AND sent_recipient_source_matches_v1(NEW,j);
 IF FOUND THEN
  NEW.bcc_addrs := recipients;
  NEW.recipient_completeness := 'complete';
  NEW.recipient_snapshot_version := 1;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_mail_index()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.raw_object_key IS NOT DISTINCT FROM OLD.raw_object_key THEN RETURN NEW; END IF;
 DELETE FROM mail_documents WHERE tenant_id=NEW.tenant_id AND message_id=NEW.id;
 IF COALESCE(NEW.raw_object_key,'')='' THEN
  DELETE FROM mail_index_jobs WHERE message_id=NEW.id; RETURN NEW;
 END IF;
 INSERT INTO mail_index_jobs(tenant_id,message_id,source_key) VALUES(NEW.tenant_id,NEW.id,NEW.raw_object_key)
 ON CONFLICT(message_id) DO UPDATE SET source_key=EXCLUDED.source_key,state='pending',attempts=0,next_attempt_at=now(),lease_token=NULL,lease_until=NULL,last_error='';
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fence_employee_enqueue()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE enabled BOOLEAN;
BEGIN
 IF NEW.sender_user_id IS NOT NULL AND NEW.sender_mailbox_id IS NOT NULL THEN
  SELECT is_active INTO enabled FROM users WHERE tenant_id=NEW.tenant_id AND id=NEW.sender_user_id FOR SHARE;
  IF enabled IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'employee sender is inactive' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.log_mailbox_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  INSERT INTO mailbox_event_log(tenant_id,mailbox_id,event_type,message_id) VALUES(OLD.tenant_id,OLD.mailbox_id,'delete',OLD.id);
  RETURN OLD;
 END IF;
 INSERT INTO mailbox_event_log(tenant_id,mailbox_id,event_type,message_id) VALUES(NEW.tenant_id,NEW.mailbox_id,CASE WHEN TG_OP='INSERT' THEN 'message' ELSE 'changed' END,NEW.id);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.permission_override_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
  RAISE EXCEPTION 'permission override identity is immutable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN
  UPDATE users SET permission_revision=nextval('permission_editor_revision_seq') WHERE id=OLD.user_id;
  RETURN OLD;
 END IF;
 UPDATE users SET permission_revision=nextval('permission_editor_revision_seq') WHERE id=NEW.user_id;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.permission_user_assignment_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.permission_profile_id IS DISTINCT FROM OLD.permission_profile_id THEN
  NEW.permission_revision := nextval('permission_editor_revision_seq');
 END IF;
 RETURN NEW;
END $function$
